defmodule ExLisp.UnicodeData do
  @moduledoc false

  @b64_data """

"""

  @hangul_l ["G", "GG", "N", "D", "DD", "R", "M", "B", "BB", "S", "SS", "", "J", "JJ", "C", "K", "T", "P", "H"]
  @hangul_v ["A", "AE", "YA", "YAE", "EO", "E", "YEO", "YE", "O", "WA", "WAE", "OE", "YO", "U", "WEO", "WE", "WI", "YU", "EU", "YI", "I"]
  @hangul_t ["", "G", "GG", "GS", "N", "NJ", "NH", "D", "L", "LG", "LM", "LB", "LS", "LT", "LP", "LH", "M", "B", "BS", "S", "SS", "NG", "J", "C", "K", "T", "P", "H"]

  defp ensure_loaded do
    case :persistent_term.get(:exlisp_unicode_code_to_name, :not_loaded) do
      :not_loaded ->
        load_tables()
      _ ->
        :ok
    end
  end

  defp load_tables do
    raw =
      @b64_data
      |> String.trim()
      |> Base.decode64!()
      |> :zlib.uncompress()

    lines = String.split(raw, "
", trim: true)

    {c2n, n2c} =
      Enum.reduce(lines, {%{}, %{}}, fn line, {c2n_acc, n2c_acc} ->
        case String.split(line, ":", parts: 2) do
          [code_str, name] ->
            code = String.to_integer(code_str)
            {Map.put(c2n_acc, code, name), Map.put(n2c_acc, name, code)}

          _ ->
            {c2n_acc, n2c_acc}
        end
      end)

    :persistent_term.put(:exlisp_unicode_code_to_name, c2n)
    :persistent_term.put(:exlisp_unicode_name_to_code, n2c)
    :ok
  end

  def code_to_name(code) when is_integer(code) do
    cond do
      code >= 0xAC00 and code <= 0xD7A3 ->
        s_index = code - 0xAC00
        l_index = div(s_index, 588)
        v_index = div(rem(s_index, 588), 28)
        t_index = rem(s_index, 28)

        l = Enum.at(@hangul_l, l_index)
        v = Enum.at(@hangul_v, v_index)
        t = Enum.at(@hangul_t, t_index)

        "HANGUL_SYLLABLE_" <> l <> v <> t

      (code >= 0x4E00 and code <= 0x9FFF) or
      (code >= 0x3400 and code <= 0x4DBF) or
      (code >= 0x20000 and code <= 0x2A6DF) or
      (code >= 0x2A700 and code <= 0x2B739) or
      (code >= 0x2B740 and code <= 0x2B81D) or
      (code >= 0x2B820 and code <= 0x2CEA1) or
      (code >= 0x2CEB0 and code <= 0x2EBE0) or
      (code >= 0x30000 and code <= 0x3134A) or
      (code >= 0x31350 and code <= 0x323AF) ->
        "CJK_UNIFIED_IDEOGRAPH_" <> Integer.to_string(code, 16)

      true ->
        ensure_loaded()
        c2n = :persistent_term.get(:exlisp_unicode_code_to_name)
        Map.get(c2n, code)
    end
  end

  def name_to_code(name) when is_binary(name) do
    norm =
      name
      |> String.upcase()
      |> String.replace(" ", "_")
      |> String.replace("-", "_")

    cond do
      String.starts_with?(norm, "CJK_UNIFIED_IDEOGRAPH_") ->
        hex = String.trim_leading(norm, "CJK_UNIFIED_IDEOGRAPH_")
        case Integer.parse(hex, 16) do
          {code, ""} -> code
          _ -> nil
        end

      true ->
        ensure_loaded()
        n2c = :persistent_term.get(:exlisp_unicode_name_to_code)
        Map.get(n2c, norm)
    end
  end
end
